class PilaConMinimo:
    def __init__(self):
        self.pila = []
        self.minimos = []

    def push(self, x):
        self.pila.append(x)
        if not self.minimos or x <= self.minimos[-1]:
            self.minimos.append(x)

    def pop(self):
        if self.pila:
            x = self.pila.pop()
            if x == self.minimos[-1]:
                self.minimos.pop()

    def get_min(self):
        return self.minimos[-1] if self.minimos else None

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

print(list(fibonacci(7)))

def quicksort(lista):
    if len(lista) <= 1:
        return lista
    pivot = lista[len(lista)//2]
    left = [x for x in lista if x < pivot]
    middle = [x for x in lista if x == pivot]
    right = [x for x in lista if x > pivot]
    return quicksort(left) + middle + quicksort(right)
